// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

import {RecordBody} from "./RecordBody.sol";

library BindingFold {
    struct OccurrenceRef {
        bytes32 envelopeId;
        uint16 leafIndex;
    }

    struct KernelIds {
        bytes32 setType;
        bytes32 tombstoneType;
        bytes32 withdrawalType;
    }

    struct Head {
        uint8 state;
        uint8 targetKind;
        uint8 tombstoneCause;
        uint32 revision;
        uint64 admissionOrdinal;
        bytes32 targetA;
        uint16 targetLeaf;
    }

    struct Effect {
        uint8 kind;
        bytes32 purpose;
        bytes32 subject;
        bytes32 fieldRole;
        uint8 targetKind;
        bytes32 targetA;
        uint16 targetLeaf;
        bool predecessorPresent;
        OccurrenceRef predecessor;
    }

    error ErrCasPredecessor(
        bytes32 bindingKey, bytes32 haveEnvelopeId, uint16 haveLeafIndex, uint64 haveOrdinal, uint32 haveRevision
    );
    error ErrCasRevision(bytes32 bindingKey, uint32 expected, uint32 have);
    error ErrRevisionGuard(bytes32 bindingKey);
    error InvalidEffect(uint8 kind);
    error InvalidOrdinal(bytes32 bindingKey, uint64 previous, uint64 proposed);
    error InvalidHead();

    bytes32 private constant DOM_POSITION = keccak256("efs2/position/1");
    bytes32 private constant DOM_BINDING = keccak256("efs2/binding/1");
    uint64 private constant ORDINAL_GUARD = (uint64(1) << 48) - 1;

    function decode(KernelIds memory ids, bytes32 typeId, RecordBody.CheckedBody memory body)
        internal
        pure
        returns (Effect memory e)
    {
        if (typeId == ids.setType) {
            e.kind = 1;
            e.purpose = word(body.fields[0], 0);
            e.subject = word(body.fields[1], 0);
            e.fieldRole = word(body.fields[2], 0);
            bool recordPresent = present(body.fields[3]);
            bool occurrencePresent = present(body.fields[4]);
            if (recordPresent == occurrencePresent) revert RecordBody.InvalidBody(17);
            if (recordPresent) {
                e.targetKind = 1;
                e.targetA = word(body.fields[3], 1);
            } else {
                e.targetKind = 2;
                e.targetA = word(body.fields[4], 1);
                e.targetLeaf = short(body.fields[4], 33);
            }
            e.predecessorPresent = present(body.fields[5]);
            if (e.predecessorPresent) {
                e.predecessor = OccurrenceRef(word(body.fields[5], 1), short(body.fields[5], 33));
            }
        } else if (typeId == ids.tombstoneType) {
            e.kind = 2;
            e.purpose = word(body.fields[0], 0);
            e.subject = word(body.fields[1], 0);
            e.fieldRole = word(body.fields[2], 0);
            e.predecessorPresent = present(body.fields[3]);
            if (e.predecessorPresent) {
                e.predecessor = OccurrenceRef(word(body.fields[3], 1), short(body.fields[3], 33));
            }
        } else if (typeId == ids.withdrawalType) {
            e.kind = 3;
            e.targetKind = 2;
            e.targetA = word(body.fields[0], 0);
            e.targetLeaf = short(body.fields[0], 32);
        }
    }

    function positionKey(Effect memory e) internal pure returns (bytes32) {
        return keccak256(abi.encode(DOM_POSITION, e.purpose, e.subject, e.fieldRole));
    }

    function bindingKey(bytes32 principalId, bytes32 position) internal pure returns (bytes32) {
        return keccak256(abi.encode(DOM_BINDING, principalId, position));
    }

    function advance(
        bytes32 key,
        Head memory beforeHead,
        OccurrenceRef memory beforeSource,
        Effect memory e,
        uint32 expectedRevision,
        uint64 newOrdinal
    ) internal pure returns (Head memory) {
        if (e.kind != 1 && e.kind != 2) revert InvalidEffect(e.kind);
        validateHead(beforeHead);
        if (e.kind == 1) {
            if (
                (e.targetKind != 1 && e.targetKind != 2) || e.targetA == bytes32(0)
                    || (e.targetKind == 1 && e.targetLeaf != 0)
            ) revert InvalidEffect(e.kind);
        } else if (e.targetKind != 0 || e.targetA != bytes32(0) || e.targetLeaf != 0) {
            revert InvalidEffect(e.kind);
        }
        if (beforeHead.state == 0) {
            if (e.predecessorPresent) revert ErrCasPredecessor(key, bytes32(0), 0, 0, 0);
        } else if (
            !e.predecessorPresent || e.predecessor.envelopeId != beforeSource.envelopeId
                || e.predecessor.leafIndex != beforeSource.leafIndex
        ) {
            revert ErrCasPredecessor(
                key, beforeSource.envelopeId, beforeSource.leafIndex, beforeHead.admissionOrdinal, beforeHead.revision
            );
        }
        if (expectedRevision != beforeHead.revision) {
            revert ErrCasRevision(key, expectedRevision, beforeHead.revision);
        }
        if (beforeHead.revision >= type(uint32).max - 1) revert ErrRevisionGuard(key);
        ordinal(key, beforeHead.admissionOrdinal, newOrdinal);

        Head memory afterHead;
        afterHead.state = e.kind == 1 ? 1 : 2;
        afterHead.revision = beforeHead.revision + 1;
        afterHead.admissionOrdinal = newOrdinal;
        if (e.kind == 1) {
            afterHead.targetKind = e.targetKind;
            afterHead.targetA = e.targetA;
            afterHead.targetLeaf = e.targetLeaf;
        } else {
            afterHead.tombstoneCause = 1;
        }
        return afterHead;
    }

    function withdrawHead(bytes32 key, Head memory beforeHead, uint64 newOrdinal)
        internal
        pure
        returns (Head memory afterHead)
    {
        validateHead(beforeHead);
        if (beforeHead.state != 1 && beforeHead.state != 2) revert InvalidHead();
        if (beforeHead.revision >= type(uint32).max - 1) revert ErrRevisionGuard(key);
        ordinal(key, beforeHead.admissionOrdinal, newOrdinal);
        afterHead.state = 2;
        afterHead.tombstoneCause = 2;
        afterHead.revision = beforeHead.revision + 1;
        afterHead.admissionOrdinal = newOrdinal;
    }

    function pack(Head memory head) internal pure returns (uint256 meta, bytes32 target) {
        validateHead(head);
        meta = uint256(head.state) | (uint256(head.revision) << 8) | (uint256(head.admissionOrdinal) << 40)
            | (uint256(head.targetKind) << 88) | (uint256(head.tombstoneCause) << 96)
            | (uint256(head.targetLeaf) << 104);
        target = head.targetA;
    }

    function unpack(uint256 meta, bytes32 target) internal pure returns (Head memory head) {
        head.state = uint8(meta);
        head.revision = uint32(meta >> 8);
        head.admissionOrdinal = uint64((meta >> 40) & ((uint256(1) << 48) - 1));
        head.targetKind = uint8(meta >> 88);
        head.tombstoneCause = uint8(meta >> 96);
        head.targetLeaf = uint16(meta >> 104);
        head.targetA = target;
    }

    function validHead(Head memory head) internal pure returns (bool) {
        if (head.state == 0) {
            return !(head.revision != 0 || head.admissionOrdinal != 0 || head.targetKind != 0
                    || head.tombstoneCause != 0 || head.targetA != bytes32(0) || head.targetLeaf != 0);
        }
        if (
            head.revision == 0 || head.revision >= type(uint32).max || head.admissionOrdinal == 0
                || head.admissionOrdinal >= ORDINAL_GUARD
        ) return false;
        if (head.state == 1) {
            return !((head.targetKind != 1 && head.targetKind != 2) || head.tombstoneCause != 0
                    || head.targetA == bytes32(0) || (head.targetKind == 1 && head.targetLeaf != 0));
        }
        if (head.state == 2) {
            return !(head.targetKind != 0 || (head.tombstoneCause != 1 && head.tombstoneCause != 2)
                    || head.targetA != bytes32(0) || head.targetLeaf != 0);
        }
        return false;
    }

    function validateHead(Head memory head) private pure {
        if (!validHead(head)) revert InvalidHead();
    }

    function ordinal(bytes32 key, uint64 previous, uint64 proposed) private pure {
        if (proposed == 0 || proposed >= ORDINAL_GUARD || proposed <= previous) {
            revert InvalidOrdinal(key, previous, proposed);
        }
    }

    function present(bytes memory option) private pure returns (bool) {
        return option[0] == 0x01;
    }

    function word(bytes memory value, uint256 offset) private pure returns (bytes32 out) {
        if (offset > value.length || value.length - offset < 32) revert RecordBody.InvalidBody(2);
        assembly ("memory-safe") { out := mload(add(add(value, 32), offset)) }
    }

    function short(bytes memory value, uint256 offset) private pure returns (uint16) {
        return (uint16(uint8(value[offset])) << 8) | uint16(uint8(value[offset + 1]));
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

import {TypeGroupParser} from "C0Admission/TypeGroupParser.sol";
import {RecordBody} from "./RecordBody.sol";

library IndexKeys {
    error InvalidDigest(uint16 algorithm, uint256 length);
    error InvalidIndex(uint8 kind, uint8 target);
    error TooManyKeys(uint256 count);

    bytes32 private constant DOM_PK = keccak256("efs2/pk/1");
    bytes32 private constant DOM_SCALAR = keccak256("efs2/vk/scalar/1");
    bytes32 private constant DOM_OCCURRENCE_VALUE = keccak256("efs2/vk/occ/1");
    bytes32 private constant DOM_DIGEST = keccak256("efs2/vk/digest/1");
    bytes32 private constant DOM_SCOPE = keccak256("efs2/vk/binding-scope/1");

    function posting(bytes32 typeId, uint8 kind, uint8 ordinal, bytes32 valueKey) internal pure returns (bytes32) {
        return keccak256(abi.encode(DOM_PK, typeId, uint256(kind), uint256(ordinal), valueKey));
    }

    function scalar(bytes memory fieldBytes) internal pure returns (bytes32) {
        return keccak256(abi.encode(DOM_SCALAR, keccak256(fieldBytes)));
    }

    function occurrenceTarget(bytes32 envelopeId, uint16 leafIndex) internal pure returns (bytes32) {
        return keccak256(abi.encode(DOM_OCCURRENCE_VALUE, envelopeId, uint256(leafIndex)));
    }

    function digest(uint16 algorithm, bytes memory digestBytes) internal pure returns (bytes32) {
        uint256 expected = algorithm == 0x11 || algorithm == 0xef01
            ? 20
            : algorithm == 0x12 || algorithm == 0x1b ? 32 : algorithm == 0x13 ? 64 : 0;
        if (expected == 0 || digestBytes.length != expected) revert InvalidDigest(algorithm, digestBytes.length);
        return keccak256(abi.encode(DOM_DIGEST, uint256(algorithm), keccak256(digestBytes)));
    }

    function scope(bytes32 principalId, bytes32 purpose, bytes32 subject) internal pure returns (bytes32) {
        return keccak256(abi.encode(DOM_SCOPE, principalId, purpose, subject));
    }

    function occurrenceKeys(
        TypeGroupParser.SchemaCache memory schema,
        RecordBody.CheckedBody memory body,
        bytes32 recordId,
        bytes32 principalId
    ) internal pure returns (bytes32[] memory keys) {
        uint256 maximum = 3 + body.references.length * 2 + schema.indexes.length;
        if (maximum > 43) revert TooManyKeys(maximum);
        keys = new bytes32[](maximum);
        uint256 count;
        count = add(keys, count, posting(bytes32(0), 3, 0, recordId));
        count = add(keys, count, posting(schema.typeId, 1, 0, bytes32(0)));
        count = add(keys, count, posting(bytes32(0), 4, 0, principalId));

        for (uint256 i; i < body.references.length; ++i) {
            RecordBody.ReferenceValue memory refValue = body.references[i];
            TypeGroupParser.RoleCache memory role = schema.roles[refValue.roleIndex];
            bytes32 targetKey =
                role.targetClass == 4 ? occurrenceTarget(refValue.targetId, refValue.leafIndex) : refValue.targetId;
            count = add(keys, count, posting(bytes32(0), 5, 0, targetKey));
            count = add(keys, count, posting(schema.typeId, 6, refValue.roleIndex, targetKey));
        }

        for (uint256 i; i < schema.indexes.length; ++i) {
            TypeGroupParser.IndexCache memory index = schema.indexes[i];
            if (index.kind == 1) {
                count = add(keys, count, posting(schema.typeId, 7, uint8(i), scalar(body.fields[index.target])));
            } else if (index.kind == 2) {
                // Reference roles already emitted the mandatory general and predicate families.
            } else if (index.kind == 3) {
                bytes memory encoded = body.fields[index.target];
                uint16 algorithm = (uint16(uint8(encoded[0])) << 8) | uint16(uint8(encoded[1]));
                uint16 length = (uint16(uint8(encoded[2])) << 8) | uint16(uint8(encoded[3]));
                bytes memory value = new bytes(length);
                for (uint256 j; j < length; ++j) {
                    value[j] = encoded[j + 4];
                }
                count = add(keys, count, posting(bytes32(0), 9, 0, digest(algorithm, value)));
            } else {
                revert InvalidIndex(index.kind, index.target);
            }
        }
        assembly ("memory-safe") { mstore(keys, count) }
    }

    function add(bytes32[] memory keys, uint256 count, bytes32 key) private pure returns (uint256) {
        for (uint256 i; i < count; ++i) {
            if (keys[i] == key) return count;
        }
        keys[count] = key;
        return count + 1;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;
import {BindingFold} from "./BindingFold.sol";

library Preparation {
    struct Config {
        address helper;
        bytes32 codehash;
    }

    struct CompiledType {
        bytes32 typeId;
        bytes cacheBytes;
    }

    struct CompiledGroup {
        bytes32 groupHash;
        bytes32 rawHash;
        CompiledType[] types;
        bytes32[] dependencies;
    }

    struct PreparedRef {
        uint8 roleIndex;
        uint8 targetClass;
        bytes32 expectedType;
        bytes32 targetId;
        uint16 leafIndex;
    }

    struct PreparedRecord {
        PreparedRef[] references;
        bytes32[] occurrenceKeys;
        BindingFold.Effect effect;
    }
    error HelperIdentity();
    error HelperOutput(uint256 length);
    error HelperInput(uint256 length);
    error InvalidPreparation();
    // PROVISIONAL experiment ceilings, not final C0 caps.
    uint256 internal constant GROUP_OUTPUT = 131072;
    uint256 internal constant PREPARED_OUTPUT = 8192;
    uint256 internal constant INPUT_MAX = 163840;
    uint256 internal constant GROUP_GAS = 15000000;
    uint256 internal constant PREPARE_GAS = 5000000;

    function invoke(Config memory c, bytes memory input, uint256 maximum, uint256 gasLimit)
        internal
        view
        returns (bytes memory output)
    {
        if (c.helper.code.length == 0 || c.helper.codehash != c.codehash) revert HelperIdentity();
        if (input.length > INPUT_MAX) revert HelperInput(input.length);
        bool ok;
        uint256 n;
        address target = c.helper;
        assembly ("memory-safe") {
            ok := staticcall(gasLimit, target, add(input, 32), mload(input), 0, 0)
            n := returndatasize()
        }
        if (n > (ok ? maximum : 1024)) revert HelperOutput(n);
        output = new bytes(n);
        assembly ("memory-safe") { returndatacopy(add(output, 32), 0, n) }
        if (!ok) assembly ("memory-safe") { revert(add(output, 32), mload(output)) }
    }

    function intrinsic(Config memory c, bytes memory raw) internal view returns (CompiledType memory) {
        return
            abi.decode(
                invoke(c, abi.encodeCall(IPreparation.compileIntrinsic, (raw)), GROUP_OUTPUT, GROUP_GAS), (CompiledType)
            );
    }

    function group(Config memory c, bytes memory raw) internal view returns (CompiledGroup memory) {
        CompiledGroup memory g = abi.decode(
            invoke(c, abi.encodeCall(IPreparation.compileGroup, (raw)), GROUP_OUTPUT, GROUP_GAS), (CompiledGroup)
        );
        if (g.types.length == 0 || g.types.length > 16 || g.dependencies.length > 256) revert InvalidPreparation();
        return g;
    }

    function record(
        Config memory c,
        bytes memory cache,
        bytes32 typeId,
        bytes memory body,
        bytes32 recordId,
        bytes32 principal,
        BindingFold.KernelIds memory ids,
        bool bodyOnly
    ) internal view returns (PreparedRecord memory r) {
        r = abi.decode(
            invoke(
                c,
                abi.encodeCall(IPreparation.prepareRecord, (cache, typeId, body, recordId, principal, ids, bodyOnly)),
                PREPARED_OUTPUT,
                PREPARE_GAS
            ),
            (PreparedRecord)
        );
        if (r.references.length > 16 || r.occurrenceKeys.length > 43) revert InvalidPreparation();
    }
}

interface IPreparation {
    function compileIntrinsic(bytes calldata raw) external view returns (Preparation.CompiledType memory);
    function compileGroup(bytes calldata raw) external view returns (Preparation.CompiledGroup memory);
    function prepareRecord(
        bytes calldata cache,
        bytes32 typeId,
        bytes calldata body,
        bytes32 recordId,
        bytes32 principal,
        BindingFold.KernelIds calldata ids,
        bool bodyOnly
    ) external view returns (Preparation.PreparedRecord memory);
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

import {TypeGroupParser} from "C0Admission/TypeGroupParser.sol";

library RecordBody {
    struct ReferenceValue {
        uint8 roleIndex;
        bytes32 targetId;
        uint16 leafIndex;
    }

    struct CheckedBody {
        bytes[] fields;
        ReferenceValue[] references;
    }
    error InvalidBody(uint16 code);

    struct Cursor {
        bytes data;
        uint256 pos;
    }

    struct Descriptor {
        uint8 kind;
        uint256 arg;
        bool hasRef;
        Descriptor[] children;
    }

    struct Walk {
        Cursor body;
        ReferenceValue[] refs;
        uint256 count;
    }

    /// @dev Consumes an admitted TypeGroupParser cache, not an untrusted schema on-ramp.
    /// No target existence, occurrence membership, Principal semantics, NFC or Files claims.
    function validate(TypeGroupParser.SchemaCache memory s, bytes memory body)
        internal
        pure
        returns (CheckedBody memory checked)
    {
        if (body.length > 8192) revert InvalidBody(3);
        checked.fields = new bytes[](s.fields.length);
        Walk memory w = Walk(Cursor(body, 0), new ReferenceValue[](16), 0);
        for (uint256 i; i < s.fields.length; ++i) {
            Cursor memory dc = Cursor(s.fields[i].descriptor, 0);
            Descriptor memory d = descriptor(dc, 1);
            if (dc.pos != dc.data.length || d.kind != s.fields[i].kind) revert InvalidBody(13);
            uint256 roleIndex = 256;
            for (uint256 j; j < s.roles.length; ++j) {
                if (s.roles[j].fieldIdx != i) continue;
                if (roleIndex != 256 || j >= 16) revert InvalidBody(16);
                roleIndex = j;
            }
            if (d.hasRef || roleIndex != 256) {
                uint8 leaf = d.kind == 11 || d.kind == 14 ? d.children[0].kind : d.kind;
                if (
                    roleIndex == 256 || !(d.kind == 7 || d.kind == 8 || d.kind == 11 || d.kind == 14)
                        || !(leaf == 7 || leaf == 8) || (d.kind == 11 && leaf != 7)
                ) revert InvalidBody(16);
                uint8 cls = s.roles[roleIndex].targetClass;
                if (cls < 1 || cls > 5 || ((leaf == 8) != (cls == 4))) revert InvalidBody(16);
            }
            uint256 start = w.body.pos;
            decode(d, w, 1, roleIndex);
            checked.fields[i] = slice(body, start, w.body.pos - start);
        }
        if (w.body.pos != body.length) revert InvalidBody(1);
        for (uint256 i; i < s.roles.length; ++i) {
            if (s.roles[i].fieldIdx >= s.fields.length) revert InvalidBody(16);
        }
        constraints(s, checked.fields);
        checked.references = new ReferenceValue[](w.count);
        for (uint256 i; i < w.count; ++i) {
            checked.references[i] = w.refs[i];
        }
    }

    function descriptor(Cursor memory c, uint256 depth) private pure returns (Descriptor memory d) {
        if (depth > 4) revert InvalidBody(11);
        skip(c, number(c, 2, 13), 13); // Names were checked at descriptor admission.
        d.kind = uint8(number(c, 1, 13));
        uint8 k = d.kind;
        if (k >= 2 && k <= 4) {
            d.arg = number(c, 1, 13);
            if (k == 4
                    ? d.arg == 0 || d.arg > 32
                    : !(d.arg == 1 || d.arg == 2 || d.arg == 4 || d.arg == 8 || d.arg == 16 || d.arg == 32)) revert InvalidBody(13);
        } else if (k == 5 || k == 6) {
            d.arg = number(c, 2, 13);
            if (d.arg > (k == 5 ? 8192 : 4096)) revert InvalidBody(13);
        } else if (k == 11 || k == 12 || k == 13 || k == 14) {
            d.arg = k == 14 ? 0 : number(c, 2, 13);
            if ((k == 11 && d.arg > 1024) || (k == 12 && d.arg > 256) || (k == 13 && (d.arg == 0 || d.arg > 64))) {
                revert InvalidBody(13);
            }
            uint256 n = k == 12 ? 2 : k == 13 ? d.arg : 1;
            d.children = new Descriptor[](n);
            for (uint256 i; i < n; ++i) {
                // Stage A runtime OPTION does not add a container depth. The existing
                // admission parser is more conservative; this does not broaden its on-ramp.
                d.children[i] = descriptor(c, k == 14 ? depth : depth + 1);
                d.hasRef = d.hasRef || d.children[i].hasRef;
            }
            if (k == 12 && !(d.children[0].kind >= 2 && d.children[0].kind <= 6)) revert InvalidBody(13);
        } else if (k == 7 || k == 8) {
            d.hasRef = true;
        } else if (!(k == 1 || k == 9 || k == 10)) {
            revert InvalidBody(13);
        }
    }

    function decode(Descriptor memory d, Walk memory w, uint256 depth, uint256 roleIndex) private pure {
        if (depth > 4) revert InvalidBody(11);
        Cursor memory c = w.body;
        uint8 k = d.kind;
        if (k == 1) {
            if (number(c, 1, 2) > 1) revert InvalidBody(7);
        } else if (k >= 2 && k <= 4) {
            skip(c, d.arg, 2);
        } else if (k == 5 || k == 6) {
            uint256 n = number(c, 2, 2);
            if (n > d.arg) revert InvalidBody(3);
            uint256 start = c.pos;
            skip(c, n, 2);
            if (k == 6) utf8(c.data, start, n, false);
        } else if (k == 7 || k == 8) {
            // OCCREF is one full-width envelope word and uint16 leaf, never two roles.
            need(c, k == 7 ? 32 : 34, 2);
            bytes32 target = bytes32(number(c, 32, 2));
            uint16 leaf = k == 8 ? uint16(number(c, 2, 2)) : 0;
            if (k == 7 && uint256(target) < 65536) revert InvalidBody(8);
            if (w.count == 16) revert InvalidBody(15);
            if (roleIndex == 256) revert InvalidBody(16);
            w.refs[w.count++] = ReferenceValue(uint8(roleIndex), target, leaf);
        } else if (k == 9) {
            skip(c, 32, 2);
        } else if (k == 10) {
            need(c, 4, 2);
            uint256 alg = number(c, 2, 2);
            uint256 n = number(c, 2, 2);
            uint256 expected = alg == 17 || alg == 61185 ? 20 : alg == 18 || alg == 27 ? 32 : alg == 19 ? 64 : 0;
            if (expected == 0 || n != expected) revert InvalidBody(9);
            skip(c, n, 2);
        } else if (k == 11 || k == 12) {
            uint256 n = number(c, 2, 2);
            if (n > d.arg) revert InvalidBody(12);
            bytes memory previous;
            for (uint256 i; i < n; ++i) {
                uint256 start = c.pos;
                decode(d.children[0], w, depth + 1, roleIndex);
                if (k == 12) {
                    bytes memory key = slice(c.data, start, c.pos - start);
                    if (i != 0 && !less(previous, key)) revert InvalidBody(5);
                    previous = key;
                    decode(d.children[1], w, depth + 1, roleIndex);
                }
            }
        } else if (k == 13) {
            for (uint256 i; i < d.children.length; ++i) {
                decode(d.children[i], w, depth + 1, roleIndex);
            }
        } else if (k == 14) {
            uint256 flag = number(c, 1, 2);
            if (flag > 1) revert InvalidBody(6);
            if (flag == 1) decode(d.children[0], w, depth, roleIndex);
        } else {
            revert InvalidBody(13);
        }
    }

    function constraints(TypeGroupParser.SchemaCache memory s, bytes[] memory fields) private pure {
        for (uint256 i; i < s.constraints.length; ++i) {
            TypeGroupParser.ConstraintCache memory x = s.constraints[i];
            if (x.fieldIdx >= fields.length) revert InvalidBody(13);
            uint8 kind = s.fields[x.fieldIdx].kind;
            Cursor memory c = Cursor(fields[x.fieldIdx], 0);
            if (x.kind == 1) {
                if (!(kind == 2 || kind == 3) || x.min > x.max) revert InvalidBody(13);
                uint256 n = c.data.length;
                uint256 raw = number(c, n, 13);
                if (kind == 2) {
                    // Do not cast a UINT(32) above INT256_MAX to a negative value.
                    if (x.max < 0 || raw > uint256(x.max) || (x.min > 0 && raw < uint256(x.min))) {
                        revert InvalidBody(14);
                    }
                } else {
                    if (n < 32 && (raw & (uint256(1) << (n * 8 - 1))) != 0) raw |= type(uint256).max << (n * 8);
                    int256 value = int256(raw);
                    if (value < x.min || value > x.max) revert InvalidBody(14);
                }
            } else if (x.kind == 2) {
                if (!(kind == 5 || kind == 6 || kind == 11 || kind == 12)) revert InvalidBody(13);
